54	/**
55	 * @brief An PhysicsJoint object connects two physics bodies together.
56	 */
57	class CC_DLL PhysicsJoint
58	{
59	protected:
60	    typedef std::function<void()> DelayTask;
61	protected:
62	    PhysicsJoint();
63	    virtual ~PhysicsJoint() = 0;
64	
65	public:
66	    /**Get physics body a connected to this joint.*/
67	    PhysicsBody* getBodyA() const { return _bodyA; }
68	    
69	    /**Get physics body b connected to this joint.*/
70	    PhysicsBody* getBodyB() const { return _bodyB; }
71	
72	    /**Get the physics world.*/
73	    PhysicsWorld* getWorld() const { return _world; }
74	    
75	    /**
76	     * Get this joint's tag.
77	     *
78	     * @return An integer number.
79	     */
80	    int getTag() const { return _tag; }
81	    
82	    /**
83	     * Set this joint's tag.
84	     *
85	     * @param tag An integer number that identifies a PhysicsJoint.
86	     */
87	    void setTag(int tag) { _tag = tag; }
88	    
89	    /** Determines if the joint is enable. */
90	    bool isEnabled() const { return _enable; }
91	
92	    /** Enable/Disable the joint. */
93	    void setEnable(bool enable);
94	    
95	    /** Determines if the collision is enable. */
96	    bool isCollisionEnabled() const { return _collisionEnable; }
97	    
98	    /** Enable/disable the collision between two bodies. */
99	    void setCollisionEnable(bool enable);
100	    
101	    /** Remove the joint from the world. */
102	    void removeFormWorld();
103	
104	    /** Set the max force between two bodies. */
105	    void setMaxForce(float force);
106	    
107	    /** Get the max force setting. */
108	    float getMaxForce() const { return _maxForce; }
109	
110	protected:
111	    bool init(PhysicsBody* a, PhysicsBody* b);
112	
113	    bool initJoint();
114	
115	    void delay(const DelayTask & task) { _delayTasks.push_back(task); }
116	
117	    void flushDelayTasks();
118	    
119	    /** Create constraints for this type joint */
120	    virtual bool createConstraints() { return false; }
121	
122	    std::vector<cpConstraint*> _cpConstraints;
123	    std::vector<DelayTask> _delayTasks;
124	    PhysicsBody* _bodyA;
125	    PhysicsBody* _bodyB;
126	    PhysicsWorld* _world;
127	
128	    WriteCache *_writeCache = nullptr;
129	
130	    bool _enable;
131	    bool _collisionEnable;
132	    bool _destroyMark;
133	    int _tag;
134	    float _maxForce;
135	
136	    bool _initDirty;
137	
138	    friend class PhysicsBody;
139	    friend class PhysicsWorld;
140	    friend class PhysicsDebugDraw;
141	};
